/* Service worker for Thành phố PDF. Generated by tools/build.mjs — edit tools/sw.template.js instead. */
const VERSION = '__VERSION__';
// path (relative to scope) -> content hash. A file is re-downloaded only when its hash changes.
const MANIFEST = __MANIFEST__;
const PREFIX = 'pdfcity-';
const CACHE = PREFIX + VERSION;
const scope = () => new URL(self.registration.scope);
const keyFor = path => new URL(`${path}?v=${MANIFEST[path]}`, scope()).href;

async function broadcast(msg){
  for (const c of await self.clients.matchAll({includeUncontrolled: true, type: 'window'})) c.postMessage(msg);
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const paths = Object.keys(MANIFEST);
    let done = 0, fetched = 0;
    const queue = [...paths];
    const work = async () => {
      for (let path; (path = queue.shift()) !== undefined;){
        const key = keyFor(path);
        const old = await caches.match(key);
        if (old) await cache.put(key, old);
        else {
          const res = await fetch(new URL(path, scope()), {cache: 'reload'});
          if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
          await cache.put(key, res);
          fetched++;
        }
        done++;
        if (done % 10 === 0 || done === paths.length) broadcast({type: 'progress', done, total: paths.length, fetched, version: VERSION});
      }
    };
    await Promise.all(Array.from({length: 6}, work));
    // First install: take over right away. Updates wait until the user agrees to reload.
    if (!self.registration.active) await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
    broadcast({type: 'ready', version: VERSION});
  })());
});

self.addEventListener('message', event => {
  if (event.data === 'skipWaiting') self.skipWaiting();
  else if (event.data === 'version') event.source?.postMessage({type: 'version', version: VERSION});
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  let path = decodeURIComponent(url.pathname.slice(scope().pathname.length));
  if (req.mode === 'navigate' || path === '') path = 'index.html';
  if (!(path in MANIFEST)) return;
  event.respondWith((async () => (await caches.match(keyFor(path))) || fetch(req))());
});
